    const f = S.f[r.fulfilmentId];
    if (f) S.E[refKey(S, f.id)] = { k: 'ref', f: f.id, s: 'ok', n: 1 };
  }
  for (const sh of q(ctx, 'carrier.shipments', { orderId: oid }, 500)) {
    const f = S.f[sh.fulfilmentId];
    if (!f) continue;
