  const files = new Map();
  for (const f of readdirSync(join(ROOT, 'api'))) files.set(`api/${f}`, readFileSync(join(ROOT, 'api', f), 'utf8'));
  for (const f of readdirSync(join(ROOT, 'constitution', 'versions'))) files.set(`constitution/versions/${f}`, readFileSync(join(ROOT, 'constitution', 'versions', f), 'utf8'));
  files.set('constitution/log.json', readFileSync(join(ROOT, 'constitution', 'log.json'), 'utf8'));
  files.set('rulebook/ed-2026-01/edition.json', JSON.stringify({ id: 'ed-2026-01', effectiveFrom: '2026-01-01' }));
  files.set('rulebook/ed-2026-01/policy.json', JSON.stringify({ fraudReviewHours: 24, customerActionHours: 48, collectionCutoffMinutes: 60 }));
  files.set('rulebook/ed-2026-01/shipping-fees.json', JSON.stringify([{ location: 'WH-A', feeMinor: 500 }, { location: 'WH-B', feeMinor: 700 }]));
  files.set('rulebook/ed-2026-01/carrier-codes.json', JSON.stringify([
    { carrier: 'DHL', code: 'C1', meaning: 'collected' }, { carrier: 'DHL', code: 'T1', meaning: 'inTransit' },
    { carrier: 'DHL', code: 'D1', meaning: 'delivered' }, { carrier: 'DHL', code: 'F1', meaning: 'collectionFailed' },
    { carrier: 'DHL', code: 'I1', meaning: 'info' },
  ]));
  files.set('master/catalog.json', JSON.stringify({ skus: [{ sku: 'SKU-1', unitPriceMinor: 1000 }, { sku: 'SKU-2', unitPriceMinor: 2500 }, { sku: 'SKU-BAD', unitPriceMinor: 100 }] }));
  files.set('master/customers.json', JSON.stringify({ customers: [{ customerId: 'C1', email: 'c1@example.test' }] }));
  return files;
}

// Validate an effect's args against api/<system>.schema.json (required, additionalProperties, types, lengths).
function validate(schema, v, path = '') {
  const errs = [];
  if (!schema) return errs;
  const type = (x) => (x === null ? 'null' : Array.isArray(x) ? 'array' : Number.isInteger(x) ? 'integer' : typeof x);
  const ok = (t, s) => (Array.isArray(s) ? s.includes(t) || (t === 'integer' && s.includes('number')) : s === t || (s === 'number' && t === 'integer'));
  if (schema.type && !ok(type(v), schema.type)) return [`${path}: type ${type(v)} not ${JSON.stringify(schema.type)}`];
  if (schema.enum && !schema.enum.includes(v)) errs.push(`${path}: ${v} not in enum`);
  if (typeof v === 'string') {
    if (schema.maxLength && v.length > schema.maxLength) errs.push(`${path}: too long`);
    if (schema.minLength && v.length < schema.minLength) errs.push(`${path}: too short`);
  }
  if (typeof v === 'number' && schema.minimum !== undefined && v < schema.minimum) errs.push(`${path}: below minimum`);
  if (typeof v === 'number' && schema.maximum !== undefined && v > schema.maximum) errs.push(`${path}: above maximum`);
  if (Array.isArray(v)) {
    if (schema.maxItems && v.length > schema.maxItems) errs.push(`${path}: too many items`);
    if (schema.minItems && v.length < schema.minItems) errs.push(`${path}: too few items`);
    v.forEach((x, i) => errs.push(...validate(schema.items, x, `${path}[${i}]`)));
  }
  if (v && typeof v === 'object' && !Array.isArray(v)) {
    for (const r of schema.required ?? []) if (!(r in v)) errs.push(`${path}.${r}: missing`);
    if (schema.additionalProperties === false) for (const k of Object.keys(v)) if (!schema.properties?.[k]) errs.push(`${path}.${k}: unknown field`);
    for (const k of Object.keys(v)) if (schema.properties?.[k]) errs.push(...validate(schema.properties[k], v[k], `${path}.${k}`));
  }
  return errs;
}

// A world: records, ledger (keyed effects), timers, tasks, instances and scheduled deliveries.
export function run(scn, { maxMinutes = 60 * 24 * 40, verbose = false } = {}) {
  const files = baseFiles();
  for (const [k, v] of Object.entries(scn.files ?? {})) files.set(k, v);
  const schemaOf = (sys, op) => JSON.parse(files.get(`api/${sys}.schema.json`)).ops[op]?.args;
  const rec = { orders: {}, fulfilments: {}, charges: [], refunds: [], reservations: [], shipments: [], notifications: [], stock: {} };
  const ledger = new Map(); // key -> { argsJSON, result }
  const log = [];
  const armErrors = [];
  const solver = createSolver();
  const q = [];   // scheduled deliveries
  let seq = 0;
  const push = (at, target, ev) => q.push({ at, seq: seq++, target, ev });
  const instances = new Map(); // id -> { carry, subject, open, n }
  let instN = 0;
  const refToInstance = new Map();
  const tasks = new Map();
  const timers = new Map(); // instance|id -> { at, onDue, version }
  const statusLog = {};
  const orderCtx = { files, instance: null };

  const ctx = (inst) => ({
    files: { get: (p) => files.get(p), keys: () => files.keys(), [Symbol.iterator]: undefined },
    query: (table, f) => {
      const [t] = table.split('.');
      const map = { orders: 'orders', fulfilments: 'fulfilments', charges: 'charges', refunds: 'refunds', reservations: 'reservations', shipments: 'shipments', notifications: 'notifications', stock: 'stock' };
      const name = table.split('.')[1];
      let rows = name === 'orders' ? Object.values(rec.orders) : name === 'fulfilments' ? Object.values(rec.fulfilments)
        : name === 'charges' ? rec.charges : name === 'refunds' ? rec.refunds : name === 'reservations' ? rec.reservations
          : name === 'shipments' ? rec.shipments : name === 'notifications' ? rec.notifications : [];
      void t; void map;
      for (const [k, v] of Object.entries(f?.where ?? {})) rows = rows.filter((r) => r[k] === v);
      return rows.slice(0, f?.limit ?? 1000);
    },
    status: (sys, key) => (ledger.has(key) ? 'committed' : 'not-found'),
    instances: ({ subject }) => [...instances.entries()].filter(([, v]) => v.open && v.subject === subject).map(([id]) => ({ instance: id })),
  });
  void orderCtx;

  // apply one effect to the world; returns the result payload
  const apply = (eff) => {
    const { key, system, op, args } = eff;
    const sch = schemaOf(system, op);
    const errs = validate(sch, args, `${system}.${op}.args`);
    if (errs.length) armErrors.push(`${system}.${op}: ${errs.join('; ')}`);
    const keyed = sch && JSON.parse(files.get(`api/${system}.schema.json`)).ops[op]?.keyed;
    const aj = JSON.stringify(args);
    if (keyed && ledger.has(key)) {
      const prev = ledger.get(key);
      if (prev.argsJSON !== aj) return { status: 'error', error: { code: 'key-conflict', retryable: false } };
      return prev.result;
    }
    const sc = scn.fault?.(system, op, args) ?? null;
    let result;
    if (sc) result = sc;
    else if (system === 'inventory' && op === 'allocate') result = { status: 'ok', result: { fulfilments: scn.plan(args.orderId) } };
    else if (system === 'fraud') result = { status: 'ok', result: { verdict: scn.verdict(args.orderId) } };
    else if (system === 'inventory' && op === 'reserve') {
      const items = args.items.map((it) => (it.sku === 'SKU-BAD' ? { key: it.key, status: 'error', error: { code: 'out-of-stock', retryable: false } } : { key: it.key, status: 'ok' }));
      for (const it of args.items) if (it.sku !== 'SKU-BAD') rec.reservations.push({ reservationId: it.key, orderId: args.orderId, fulfilmentId: args.fulfilmentId, location: args.location, sku: it.sku, qty: it.qty, status: 'active' });
      const bad = items.some((x) => x.status !== 'ok');
      result = bad ? { status: 'partial', items } : { status: 'ok', items };
    } else if (system === 'inventory' && op === 'release') {
      for (const r of rec.reservations) if (r.fulfilmentId === args.fulfilmentId && r.sku === args.sku && r.status === 'active') r.status = 'released';
      result = { status: 'ok' };
    } else if (system === 'billing' && op === 'charge') {
      if (scn.declines?.includes(args.fulfilmentId)) result = { status: 'error', error: { code: 'card-declined', retryable: false, http: 402 } };
      else { rec.charges.push({ chargeId: key, orderId: args.orderId, fulfilmentId: args.fulfilmentId, customerId: args.customerId, amountMinor: args.amountMinor, currency: args.currency, refundedMinor: 0 }); result = { status: 'ok' }; }
    } else if (system === 'billing' && op === 'refund') {
      const c = rec.charges.find((x) => x.fulfilmentId === args.fulfilmentId);
      if (c) c.refundedMinor += args.amountMinor;
      rec.refunds.push({ refundId: key, chargeId: c?.chargeId, orderId: args.orderId, fulfilmentId: args.fulfilmentId, amountMinor: args.amountMinor });
      result = { status: 'ok' };
    } else if (system === 'carrier' && op === 'create') {
      rec.shipments.push({ shipmentId: `SH-${key}`, orderId: args.orderId, fulfilmentId: args.fulfilmentId, location: args.location, carrier: 'DHL', status: 'created', ref: args.ref ?? null });
      if (args.ref) refToInstance.set(args.ref, eff.instance);
      result = { status: 'ok' };
    } else if (system === 'carrier' && op === 'cancel') {
      const s = rec.shipments.find((x) => x.fulfilmentId === args.fulfilmentId);
      if (s?.status === 'collected') result = { status: 'error', error: { code: 'already-collected', retryable: false, http: 409 } };
      else { if (s) s.status = 'cancelled'; result = { status: 'ok' }; }
    } else if (system === 'orders' && op === 'create') {
      rec.orders[args.orderId] = { orderId: args.orderId, customerId: args.customerId, status: 'pending', placedAt: args.placedAt, currency: args.currency, items: args.items, totalMinor: args.totalMinor };
      for (const f of args.fulfilments) rec.fulfilments[f.fulfilmentId] = { fulfilmentId: f.fulfilmentId, orderId: args.orderId, location: f.location, items: f.items, amountMinor: f.amountMinor, status: f.location === null ? 'unavailable' : 'pending' };
      result = { status: 'ok' };
    } else if (system === 'orders' && op === 'setStatus') {
      const target = args.fulfilmentId ? rec.fulfilments[args.fulfilmentId] : rec.orders[args.orderId];
      (statusLog[args.fulfilmentId ?? args.orderId] ??= []).push(args.status);
      if (target) target.status = args.status;
      result = { status: 'ok' };
    } else if (system === 'notify' && op === 'send') {
      rec.notifications.push({ notificationId: key, to: args.to, about: args.about, template: args.template, text: args.text });
      result = { status: 'ok' };
    } else result = { status: 'ok' };
    ledger.set(key, { argsJSON: aj, result, system, op, args });
    return result;
  };

  const deliverOut = (instId, out, at) => {
    const inst = instances.get(instId);
    if (!inst) return;
    if (out.decisions?.subject !== undefined) inst.subject = out.decisions.subject;
    inst.carry = JSON.parse(JSON.stringify(out.carry));
    const size = JSON.stringify(out.carry).length;
    if (size > 64 * 1024) armErrors.push(`carry ${size} bytes`);
    if (out.decisions === undefined || !('subject' in out.decisions)) armErrors.push('decisions.subject missing');
    for (const eff of out.effects ?? []) {
      const r = apply({ ...eff, instance: instId });
      push(at + MIN, instId, { id: `res-${seq}`, type: 'effect.result', at: iso(at + MIN), source: eff.system, channel: { kind: 'instance', instance: instId }, payload: { key: eff.key, system: eff.system, op: eff.op, ...r } });
    }
    for (const u of out.obligations?.upsert ?? []) {
      const due = Math.max(Date.parse(u.dueAt), at + MIN);
      timers.set(`${instId}|${u.id}`, { at: due, onDue: u.onDue, id: u.id });
      push(due, instId, { id: `tm-${u.id}-${seq}`, type: 'timer.fired', at: iso(due), source: 'timer', channel: { kind: 'instance', instance: instId }, payload: { obligationId: u.id, onDue: u.onDue }, _timer: `${instId}|${u.id}` });
    }
    for (const id of out.obligations?.cancel ?? []) timers.delete(`${instId}|${id}`);
    for (const t of out.humanTasks ?? []) {
      tasks.set(t.id, { ...t, instance: instId, answered: false });
      const ans = scn.answer?.(t, tasks);
      if (ans) push(at + ans.delay * MIN, instId, { id: `ans-${t.id}-${seq}`, type: 'humanTask.answered', at: iso(at + ans.delay * MIN), source: 'actor', channel: { kind: 'instance', instance: instId }, payload: { taskId: t.id, user: ans.user, answer: ans.answer, late: false } });
      if (ans && ans.kind) push(at + ans.delay * MIN, instId, { id: `x-${t.id}-${seq}`, type: ans.kind, at: iso(at + ans.delay * MIN), source: 'actor', channel: { kind: 'instance', instance: instId }, payload: { taskId: t.id, user: ans.user } });
      push(Date.parse(t.dueAt) + 0, instId, { id: `to-${t.id}-${seq}`, type: 'humanTask.timeout', at: t.dueAt, source: 'actor', channel: { kind: 'instance', instance: instId }, payload: { taskId: t.id } });
    }
    if (out.close) { inst.open = false; }
  };

  // scripted external inputs
  for (const e of scn.inbound ?? []) push(T0 + e.at * MIN, 'inbound', { id: e.id ?? `in-${seq}`, type: e.type, at: iso(T0 + e.at * MIN), source: e.source, channel: { kind: 'inbound' }, payload: e.payload });
  for (const c of scn.carrier ?? []) {
    const at = T0 + c.at * MIN;
    push(at, 'carrier', { id: `car-${seq}`, type: 'carrier.status', at: iso(at), source: 'carrier', channel: { kind: 'inbound' }, payload: { ref: c.ref, carrier: 'DHL', code: c.code, shipmentId: c.shipmentId ?? `SH-${c.fid}`, fulfilmentRef: c.fid, reportedAt: iso(T0 + (c.reported ?? c.at) * MIN) } });
  }

  let steps = 0;
  while (q.length && steps++ < 200000) {
    q.sort((a, b) => a.at - b.at || a.seq - b.seq);
    const t = q[0].at;
    if (t - T0 > maxMinutes * MIN) break;
    const batch = q.filter((x) => x.at === t);
    q.splice(0, batch.length);
    // skip timers that were cancelled or superseded
    const live = batch.filter((x) => !x.ev._timer || (timers.get(x.ev._timer) && timers.get(x.ev._timer).at === t));
    // inbound items start new instances
    const groups = new Map();
    for (const x of live) {
      if (x.target === 'inbound' || x.target === 'carrier') {
        const ref = x.ev.payload?.ref;
        if (x.ev.type === 'carrier.status' && ref && refToInstance.has(ref) && instances.get(refToInstance.get(ref))?.open) {
          const id = refToInstance.get(ref);
          groups.set(id, [...(groups.get(id) ?? []), x.ev]);
          continue;
        }
        const id = `i-${String(++instN).padStart(4, '0')}`;
        instances.set(id, { carry: null, subject: null, open: true });
        const r = [x.ev];
        const out = call(id, r, t, true);
        if (out?.merge) {
          const target = out.merge.into;
          instances.get(id).open = false;
          if (instances.get(target)?.open) push(t, target, x.ev);
          else armErrors.push(`merge into closed ${target}`);
        }
        continue;
      }
      if (!instances.get(x.target)?.open) { if (verbose) log.push(`dropped ${x.ev.type} to closed ${x.target}`); continue; }
      groups.set(x.target, [...(groups.get(x.target) ?? []), x.ev]);
    }
    for (const [id, evs] of groups) call(id, evs, t, false);
  }

  function call(id, evs, t, fresh) {
    const inst = instances.get(id);
    const input = { kind: 'case', item: 'E8', world: 'practice', instance: id, now: iso(t), events: evs, carry: fresh ? null : inst.carry };
    let out;
    try {
      out = solver.tick(input, ctx(id));
    } catch (e) {
      armErrors.push(`crash: ${e.stack}`);
      return null;
    }
    if (out.merge) return out;
    deliverOut(id, out, t);
    return out;
  }

  return { rec, ledger, armErrors, statusLog, tasks, instances, log, timers };
}

export function summary(res) {
  const eff = [...res.ledger.values()].map((e) => `${e.system}.${e.op} ${e.args.fulfilmentId ?? e.args.orderId} ${e.args.status ?? e.args.template ?? ''}`);
  return {
    orders: Object.values(res.rec.orders).map((o) => `${o.orderId}:${o.status}`),
    fulfilments: Object.values(res.rec.fulfilments).map((f) => `${f.fulfilmentId}:${f.status}`),
    charges: res.rec.charges.map((c) => `${c.fulfilmentId}:${c.amountMinor}:refunded=${c.refundedMinor}`),
    refunds: res.rec.refunds.map((r) => `${r.fulfilmentId}:${r.amountMinor}`),
    reservations: res.rec.reservations.map((r) => `${r.sku}:${r.status}`),
    shipments: res.rec.shipments.map((s) => `${s.fulfilmentId}:${s.status}`),
    notifications: res.rec.notifications.map((n) => `${n.template}->${n.to}(${n.about})`),
    armErrors: res.armErrors,
    effects: eff.length,
    openInstances: [...res.instances.entries()].filter(([, v]) => v.open).map(([k]) => k),
    tasks: [...res.tasks.values()].map((t) => `${t.id}[${t.kind}/${t.role}]${t.excludeUsers ? ' excl=' + t.excludeUsers.join(',') : ''}`),
  };
}

const PLAN_OK = (orderId) => [
  { fulfilmentId: `${orderId}-A`, location: 'WH-A', items: [{ sku: 'SKU-1', qty: 2 }], available: true },
];
export const SCENARIOS = {
  happy: {
    inbound: [{ at: 0, type: 'order.placed', source: 'shop', payload: { orderId: ' #ord-1001-0007', customerId: 'C1', placedAt: iso(T0), currency: 'EUR', items: [{ sku: 'SKU-1', qty: 2 }], channel: 'web' } }],
    plan: (o) => PLAN_OK('ORD-1001-0007'),
    verdict: () => 'pass',
    carrier: [{ at: 600, ref: 'ORD-1001-0007/ORD-1001-0007-A', fid: 'ORD-1001-0007-A', code: 'C1' }, { at: 900, ref: 'ORD-1001-0007/ORD-1001-0007-A', fid: 'ORD-1001-0007-A', code: 'D1' }],
  },
};
if (process.argv[1] && process.argv[1].endsWith('sim.mjs')) {
  const name = process.argv[2] ?? 'happy';
  const res = run(SCENARIOS[name]);
  console.log(JSON.stringify(summary(res), null, 1));
}

