  if (!FULFIL_TERMINAL.has(status) && (FULFIL_RANK[status] ?? 9) <= (FULFIL_RANK[f.st] ?? -1)) return;
  f.st = status;
  S.q.push({ k: 'st', f: id, t: status, mv: mv ?? null });
}
function failF(S, id) {
  const f = S.f[id];
