  const out = {};
  for (const k of Object.keys(v)) {
    if (v[k] === undefined) continue;
    let name = k;
    if (names.length && !names.includes(k)) name = names.find((n) => norm(n) === norm(k)) ?? k;
    out[name] = fit(props ? props[name] : undefined, v[k]);
