  let retryable;
  if (e && typeof e === 'object' && 'retryable' in e) retryable = !!e.retryable;
  else if (x && 'retryable' in x) retryable = !!x.retryable;
  const http = Number(e?.http ?? e?.httpStatus ?? x?.httpStatus ?? NaN);
  return {
