  if (!t) return true;
  const types = Array.isArray(t) ? t : [t];
  const kind = x === null ? 'null' : Number.isInteger(x) ? 'integer' : typeof x;
  return types.includes(kind) || (kind === 'integer' && types.includes('number')) || (x === null && types.includes('null'));
